// Draws icon.png (48x72, the Plugin Hub maximum). Regenerate from the repo root with:
//   java docs/icon/Icon.java icon.png /tmp/icon-preview
//
// Dieter Rams-style badge: a flat dark tile, a one-line W, and one amber
// needle rising from the W's centre point (amber is the strip's caret
// colour, "where you are pointing"). No shading, no outline, one accent.
import java.awt.*; import java.awt.geom.*; import java.awt.image.*; import javax.imageio.*; import java.io.*;
public class Icon {
  static final Color TILE = new Color(0x35, 0x32, 0x2D);   // lifted from #2B2A28 so it reads on RuneLite's #1E1E1E
  static final Color WHITE = new Color(0xF2, 0xF0, 0xEB);  // Braun white
  static final Color AMBER = new Color(0xE8, 0xA0, 0x20);  // Palette.AMBER
  public static void main(String[] a) throws Exception {
    int W = 48, H = 72, K = 8;                            // draw at 8x, area-average down
    BufferedImage big = new BufferedImage(W*K, H*K, BufferedImage.TYPE_INT_ARGB);
    Graphics2D g = big.createGraphics();
    g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
    g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
    g.scale(K, K);
    g.setColor(TILE); g.fill(new RoundRectangle2D.Double(4, 12, 40, 48, 16, 16));
    // W on whole-pixel vertices, stroke 3px, mitred joints
    Path2D w = new Path2D.Double(); w.moveTo(13, 31); w.lineTo(18.5, 51); w.lineTo(24, 38); w.lineTo(29.5, 51); w.lineTo(35, 31);
    g.setColor(WHITE); g.setStroke(new BasicStroke(3f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f)); g.draw(w);
    // needle from the W's centre point up to the tile's top padding
    Path2D n = new Path2D.Double(); n.moveTo(24, 18); n.lineTo(26.2, 37); n.lineTo(21.8, 37); n.closePath();
    g.setColor(AMBER); g.fill(n);
    g.dispose();
    BufferedImage out = new BufferedImage(W, H, BufferedImage.TYPE_INT_ARGB);
    Graphics2D o = out.createGraphics(); o.drawImage(big.getScaledInstance(W, H, Image.SCALE_AREA_AVERAGING), 0, 0, null); o.dispose();
    ImageIO.write(out, "png", new File(a[0]));
    // previews: 1x and 4x on RuneLite's dark panel and on light
    for (String[] bg : new String[][]{{"dark","1E1E1E"},{"light","E6E6E6"}}) {
      BufferedImage p = new BufferedImage(W*5 + 30, H*4 + 20, BufferedImage.TYPE_INT_RGB);
      Graphics2D pg = p.createGraphics(); pg.setColor(new Color(Integer.parseInt(bg[1],16))); pg.fillRect(0,0,p.getWidth(),p.getHeight());
      pg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
      pg.drawImage(out, 10, 10, W*4, H*4, null); pg.drawImage(out, W*4 + 20, 10 + H*3/2, W, H, null); pg.dispose();
      ImageIO.write(p, "png", new File(a[1] + "-" + bg[0] + ".png"));
    }
  }
}

package com.wayfarer;

/**
 * Pure math for the compass strip: camera yaw (JAU14) to compass bearing,
 * and bearing deltas to horizontal strip positions. No RuneLite types, so
 * every function here is covered directly by CompassMathTest.
 *
 * Convention, derived from live source and worth restating because it is
 * easy to get backwards:
 *
 * - Camera yaw 0 faces NORTH, and increasing yaw turns the camera
 *   COUNTERCLOCKWISE on the compass (N -> W -> S -> E). Derived from
 *   Perspective#localToCanvasCpu: forward at yaw theta is
 *   (-sin theta, cos theta) in world axes, with dy=+1 = north per
 *   WorldArea#canTravelInDirection.
 * - Compass bearing runs the opposite way, CLOCKWISE from north
 *   (N=0, E=90, S=180, W=270), because that's what every compass in
 *   every game HUD means.
 *
 * Hence the sign flip in bearingDegrees(): bearing = -yaw, wrapped.
 */
final class CompassMath
{
	static final int JAU14_FULL_CIRCLE = 16384;

	private CompassMath()
	{
	}

	/**
	 * Camera yaw (JAU14, 0-16383, counterclockwise from north) to compass
	 * bearing in degrees (0-360, clockwise from north: N=0, E=90).
	 */
	static double bearingDegrees(int yawJau14)
	{
		int wrapped = Math.floorMod(JAU14_FULL_CIRCLE - yawJau14, JAU14_FULL_CIRCLE);
		return wrapped * 360.0 / JAU14_FULL_CIRCLE;
	}

	/**
	 * Signed shortest angular distance from heading to feature, in degrees,
	 * in [-180, 180). Positive means the feature sits clockwise of the
	 * heading, i.e. renders right of the strip's center.
	 */
	static double signedDeltaDegrees(double featureBearing, double headingBearing)
	{
		double delta = (featureBearing - headingBearing) % 360.0;
		if (delta < -180.0)
		{
			delta += 360.0;
		}
		else if (delta >= 180.0)
		{
			delta -= 360.0;
		}
		return delta;
	}

	/**
	 * Horizontal position of a feature on the strip as a fraction of the
	 * strip's half-width: 0 = center, -1/+1 = left/right edge. Callers
	 * cull anything with |fraction| > 1 rather than clamping, so features
	 * scroll off the ends instead of piling up there.
	 */
	static double screenOffsetFraction(double signedDeltaDegrees, double halfSpanDegrees)
	{
		return signedDeltaDegrees / halfSpanDegrees;
	}

	/**
	 * Compass bearing (degrees, clockwise from north) from me toward a
	 * target, given the world-axis delta: dxEast = target x - my x
	 * (positive east), dyNorth = target y - my y (positive north), both
	 * per WorldArea#canTravelInDirection's sign convention.
	 * atan2(east, north) is bearing by definition: due north (0, +1) is
	 * 0, due east (+1, 0) is 90.
	 */
	static double bearingToTarget(int dxEast, int dyNorth)
	{
		double bearing = Math.toDegrees(Math.atan2(dxEast, dyNorth));
		return bearing < 0 ? bearing + 360.0 : bearing;
	}

	/**
	 * Eases a marker's shown bearing toward its true bearing so nothing
	 * on the strip moves in a jarring snap: an exponential approach with
	 * time constant tauSeconds, and never faster than maxDegreesPerSecond.
	 * Takes the short way round across north. Only the target's world
	 * bearing is eased — the camera heading is not — so turning the camera
	 * still moves the tape and every marker instantly.
	 */
	static double smoothBearing(double shown, double target, double dtSeconds, double tauSeconds, double maxDegreesPerSecond)
	{
		if (dtSeconds <= 0)
		{
			return shown;
		}
		double delta = signedDeltaDegrees(target, shown);
		double step = delta * (1.0 - Math.exp(-dtSeconds / tauSeconds));
		double cap = maxDegreesPerSecond * dtSeconds;
		step = Math.max(-cap, Math.min(cap, step));
		double result = (shown + step) % 360.0;
		return result < 0 ? result + 360.0 : result;
	}

	/**
	 * Marker range under "range follows zoom": the full range when zoomed
	 * all the way out (zoomIn 0), shrinking linearly to minFraction of it
	 * when zoomed all the way in (zoomIn 1). Never below floorTiles (or the
	 * full range, if that is smaller).
	 */
	static double zoomedRange(double rangeTiles, double zoomIn, double minFraction, double floorTiles)
	{
		double z = Math.max(0.0, Math.min(1.0, zoomIn));
		return Math.max(Math.min(floorTiles, rangeTiles), rangeTiles * (1.0 - (1.0 - minFraction) * z));
	}

	/**
	 * True when a marker's true bearing has jumped more than snapDegrees from
	 * where it is shown — e.g. someone running straight through you, whose
	 * bearing flips ~180 degrees. Easing that would slide the marker the
	 * long way across the strip; the caller snaps and fades it instead.
	 */
	static boolean isFlip(double shown, double target, double snapDegrees)
	{
		return Math.abs(signedDeltaDegrees(target, shown)) > snapDegrees;
	}

	/** Fade-in for a marker that appeared or snapped ageSeconds ago: 0 -> 1 over fadeSeconds. */
	static double appearFade(double ageSeconds, double fadeSeconds)
	{
		return Math.max(0.0, Math.min(1.0, ageSeconds / fadeSeconds));
	}

	/**
	 * Near-field fade for markers. Bearing to a moving actor changes at
	 * speed / distance, so something passing within a tile or two swings
	 * across the whole strip in a fraction of a second — the most
	 * eye-catching motion on the HUD, for the actor you can already see
	 * in the scene. Returns floor at distance 0, rising linearly to 1.0 at
	 * fadeTiles and beyond. Quiets the flick without delaying or moving
	 * the marker, so it still points truthfully.
	 */
	static double nearFade(double distanceTiles, double fadeTiles, double floor)
	{
		if (distanceTiles >= fadeTiles)
		{
			return 1.0;
		}
		return floor + (1.0 - floor) * Math.max(0.0, distanceTiles) / fadeTiles;
	}

	/**
	 * Linear mapping from distance (0 = beside you, 1 = range cap) to a
	 * pixel value, clamped to [near, far]. Used for marker height (near at
	 * the bottom rail, far rising toward the top, like distant objects
	 * sitting higher toward the horizon) and marker size (near large, far
	 * small).
	 */
	static int byDistance(double distanceFraction, int near, int far)
	{
		double f = Math.max(0.0, Math.min(1.0, distanceFraction));
		return (int) Math.round(near + (far - near) * f);
	}

	/**
	 * Edge fade for strip elements: full alpha through the middle, linear
	 * fade to zero over the outer fadeZone fraction of each side. Input
	 * fraction is the screenOffsetFraction value, output is 0..1.
	 */
	static double edgeAlpha(double offsetFraction, double fadeZone)
	{
		double edgeDistance = 1.0 - Math.abs(offsetFraction);
		if (edgeDistance <= 0)
		{
			return 0;
		}
		if (edgeDistance >= fadeZone)
		{
			return 1.0;
		}
		return edgeDistance / fadeZone;
	}
}

package com.wayfarer;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Singleton;
import net.runelite.api.ItemLayer;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.WorldView;

/**
 * Tiles holding ground items in the top-level world, kept from item
 * spawn/despawn events so the overlay never scans the scene per frame.
 * One marker per tile, like the minimap's red dot, however many items
 * are stacked there.
 *
 * All calls arrive on the client thread (events, the startup seed, and
 * overlay rendering), so a plain HashMap is enough.
 */
@Singleton
class GroundItemTiles
{
	/** Tile -> number of item stacks on it. */
	private final Map<Tile, Integer> counts = new HashMap<>();

	void spawned(Tile tile)
	{
		if (isTopLevel(tile))
		{
			counts.merge(tile, 1, Integer::sum);
		}
	}

	void despawned(Tile tile)
	{
		// Returning null from the remapping function removes the entry.
		counts.computeIfPresent(tile, (t, n) -> n > 1 ? n - 1 : null);
	}

	/** The scene reloaded; every tile we hold belongs to the old one. */
	void unloaded(WorldView worldView)
	{
		if (worldView.isTopLevel())
		{
			counts.clear();
		}
	}

	/**
	 * Item spawn events already fired for items present before the
	 * plugin started, so read them once from the scene. A single pass at
	 * startup, not per frame.
	 */
	void seed(WorldView worldView)
	{
		counts.clear();
		Scene scene = worldView.getScene();
		for (Tile[][] plane : scene.getTiles())
		{
			for (Tile[] row : plane)
			{
				for (Tile tile : row)
				{
					if (tile == null)
					{
						continue;
					}
					List<TileItem> items = tile.getGroundItems();
					if (items != null && !items.isEmpty())
					{
						counts.put(tile, items.size());
					}
				}
			}
		}
	}

	void clear()
	{
		counts.clear();
	}

	Set<Tile> tiles()
	{
		return Collections.unmodifiableSet(counts.keySet());
	}

	/**
	 * Items on boats (Sailing) live in the boat's own world view, whose
	 * local coordinates don't line up with the main world's; they are
	 * left out, the same as actors aboard other boats.
	 */
	private static boolean isTopLevel(Tile tile)
	{
		ItemLayer layer = tile.getItemLayer();
		WorldView view = layer == null ? null : layer.getWorldView();
		return view != null && view.isTopLevel();
	}
}

package com.wayfarer;

import java.util.HashMap;
import java.util.Map;

/**
 * Minimap icon categories grouped into the plugin's toggles. Category ids
 * and their names come from the game's world-map key (cache enum 1713,
 * category -> name), read from a cache dump on 2026-09-26 and cross-checked
 * live: the ids logged in-game (Bank 1055, General store 1049, Anvil 1060...)
 * matched it exactly. Every category in that key is listed here once.
 */
enum IconGroup
{
	BANKS(
		1055, // Bank
		1126 // Grand Exchange
	),
	ALTARS(
		1070 // Altar
	),
	SHOPS(
		1049, 1050, 1052, 1053, 1054, 1057, 1064, 1065, 1066, 1067, 1068, 1069, 1072, 1073, 1074, 1075,
		1076, 1078, 1079, 1080, 1081, 1082, 1083, 1090, 1093, 1094, 1095, 1096, 1097, 1106, 1113, 1122,
		1123, 1125, 1128, 1266, 1267, 1269, 1270, 1272, 1273, 1274, 1790, 1071
	),
	RARE_TREES(
		1085 // Rare trees
	),
	TRANSPORT(
		1104, // Transportation
		1105, // House portal
		1117, // Agility shortcut
		2505, // Agility shortcut (one way)
		2393 // Docking point
	),
	SKILLING(
		1058, 1059, 1060, 1061, 1077, 1084, 1086, 1088, 1089, 1091, 1092, 1098, 1101, 1107, 1108, 1109,
		1110, 1111, 1115, 1118, 1396, 1425, 1641, 1642, 1643, 2002, 2261, 2386, 2388, 2390
	),
	MINIGAMES(
		1087, // Minigame
		1716, // Raid
		1499, // Distraction & Diversion
		2387, // Barracuda Trial
		1119 // Holiday event
	),
	SLAYER(
		1099 // Slayer Master
	),
	QUESTS(
		1056 // Quest
	),
	DUNGEONS(
		1062 // Dungeon
	),
	SERVICES(
		1100, 1102, 1112, 1114, 1116, 1120, 1121, 1250, 1251, 1252, 1253, 1254, 1255, 1256, 1257, 1258,
		1259, 1260, 1261, 1262, 1263, 1264, 1265, 1268, 1271, 1275, 1317, 176, 1459, 1551, 1579, 2389,
		2391, 2392, 2394, 1063
	);

	private final int[] categories;

	IconGroup(int... categories)
	{
		this.categories = categories;
	}

	private static final Map<Integer, IconGroup> BY_CATEGORY = new HashMap<>();

	static
	{
		for (IconGroup group : values())
		{
			for (int category : group.categories)
			{
				IconGroup previous = BY_CATEGORY.put(category, group);
				if (previous != null)
				{
					throw new IllegalStateException("category " + category + " in both " + previous + " and " + group);
				}
			}
		}
	}

	/** The group for a minimap icon category, or null for one the key doesn't list. */
	static IconGroup forCategory(int category)
	{
		return BY_CATEGORY.get(category);
	}

	static int categoryCount()
	{
		return BY_CATEGORY.size();
	}
}

package com.wayfarer;

import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.ObjectComposition;
import net.runelite.api.SpritePixels;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.worldmap.MapElementConfig;

/**
 * Scenery in the top-level world that carries a minimap icon (banks,
 * altars, shops, rare trees...), kept from object spawn/despawn events so
 * the overlay never scans the scene per frame. The icon is the object's
 * own map function, the same one the minimap draws.
 *
 * Discovery: which icon ids mean "bank" or "altar" isn't named anywhere
 * in the API, so each new icon id is logged once at debug level with its
 * category and the object's name. The toggle groups are built from that.
 *
 * All calls arrive on the client thread (spawn events), so plain
 * collections are enough.
 */
@Slf4j
@Singleton
class MapIconObjects
{
	/** Object -> its minimap icon id. */
	private final Map<TileObject, Integer> icons = new HashMap<>();
	/** Icon ids already logged, so discovery prints each one once. */
	private final Set<Integer> logged = new HashSet<>();
	/** Per icon id, looked up once: its world-map category and its sprite. */
	private final Map<Integer, Integer> categories = new HashMap<>();
	private final Map<Integer, BufferedImage> sprites = new HashMap<>();

	private final Client client;

	@Inject
	MapIconObjects(Client client)
	{
		this.client = client;
	}

	void spawned(TileObject object)
	{
		WorldView view = object.getWorldView();
		if (view == null || !view.isTopLevel())
		{
			return; // boat scenery: not on the main-world minimap
		}
		ObjectComposition def = client.getObjectDefinition(object.getId());
		if (def == null)
		{
			return;
		}
		if (def.getImpostorIds() != null && def.getImpostor() != null)
		{
			def = def.getImpostor();
		}
		int iconId = def.getMapIconId();
		if (iconId < 0)
		{
			return;
		}
		icons.put(object, iconId);
		if (logged.add(iconId))
		{
			log.debug("Wayfarer map icon: icon={} category={} object={} '{}' at {}",
				iconId, category(iconId), object.getId(), def.getName(),
				object.getWorldLocation());
		}
	}

	void despawned(TileObject object)
	{
		icons.remove(object);
	}

	/**
	 * Spawn events already fired for scenery present before the plugin
	 * started, so read the scene once. A single pass at startup, not per
	 * frame (same as GroundItemTiles.seed).
	 */
	void seed(WorldView worldView)
	{
		icons.clear();
		for (Tile[][] plane : worldView.getScene().getTiles())
		{
			for (Tile[] row : plane)
			{
				for (Tile tile : row)
				{
					if (tile == null)
					{
						continue;
					}
					GameObject[] objects = tile.getGameObjects();
					if (objects != null)
					{
						for (GameObject object : objects)
						{
							spawnedIfPresent(object);
						}
					}
					spawnedIfPresent(tile.getWallObject());
					spawnedIfPresent(tile.getDecorativeObject());
					spawnedIfPresent(tile.getGroundObject());
				}
			}
		}
	}

	private void spawnedIfPresent(TileObject object)
	{
		if (object != null)
		{
			spawned(object);
		}
	}

	/** The scene reloaded; every object we hold belongs to the old one. */
	void unloaded(WorldView worldView)
	{
		if (worldView.isTopLevel())
		{
			icons.clear();
		}
	}

	void clear()
	{
		icons.clear();
	}

	/** World-map category of an icon id (see IconGroup), cached. */
	int category(int iconId)
	{
		return categories.computeIfAbsent(iconId, id ->
		{
			MapElementConfig config = client.getMapElementConfig(id);
			return config == null ? -1 : config.getCategory();
		});
	}

	/** The icon's own minimap sprite, cached; null if the game has none. */
	BufferedImage sprite(int iconId)
	{
		if (!sprites.containsKey(iconId))
		{
			MapElementConfig config = client.getMapElementConfig(iconId);
			SpritePixels pixels = config == null ? null : config.getMapIcon(false);
			sprites.put(iconId, pixels == null ? null : pixels.toBufferedImage());
		}
		return sprites.get(iconId);
	}

	Map<TileObject, Integer> icons()
	{
		return Collections.unmodifiableMap(icons);
	}
}

package com.wayfarer;

import java.awt.Color;

/**
 * The plugin's entire color vocabulary, in one place. Braun-derived warm
 * neutrals (Rams: color as function, one accent per view) chosen to sit
 * inside RuneScape's parchment-and-gold aesthetic rather than fight it.
 *
 * Rules this file enforces by construction:
 * - One accent: AMBER, and it means exactly one thing — "where you are
 *   pointing" (the compass caret). Nothing else may be amber.
 * - Ticks are aged paper, never pure white: pure #FFFFFF reads as UI
 *   chrome laid over the scene; paper reads as part of the world. Labels
 *   use SNOW_WHITE (still not pure white), which keeps 4.5:1 over bright
 *   scenery down to a 54% strip where PAPER needs 65% (contrast-sweep).
 * - Surfaces are warm black, never pure black or cool gray.
 * - Marker colors are classification, nothing else. They are the defaults;
 *   players can recolor markers in the config panel.
 */
final class Palette
{
	/** Aged paper — ticks and cardinal letters. */
	static final Color PAPER = new Color(0xD4, 0xCC, 0xBC);

	/** Warm black — the strip surface. */
	static final Color WARM_BLACK = new Color(0x0A, 0x09, 0x07);

	/** The single accent: dial-illumination amber. Pointing only. */
	static final Color AMBER = new Color(0xE8, 0xA0, 0x20);

	/**
	 * Marker for attackable NPCs (combat level &gt; 0). Signal orange: the
	 * warning colour, one step short of alarm red, and far enough round
	 * the hue wheel from AMBER (~22 vs ~38 degrees, with RESULT_YELLOW at
	 * ~52) that the pointing accent stays unique.
	 */
	static final Color SIGNAL_ORANGE = new Color(0xE8, 0x70, 0x2A);

	/**
	 * Marker for ground items. Red because the minimap already draws items
	 * as red dots: color as function means matching the meaning players
	 * already know. Deliberately dark (CIE L* ~42): at 4px, colours are told
	 * apart by lightness more than hue, so the warm markers step down in
	 * lightness — white 96, yellow 75, orange 61, red 42.
	 */
	static final Color SIGNAL_RED = new Color(0xB8, 0x30, 0x2A);

	/**
	 * Marker for other players. Braun snow white — deliberately brighter
	 * than PAPER so player dots read above the tape's own marks.
	 */
	static final Color SNOW_WHITE = new Color(0xF5, 0xF2, 0xED);

	/**
	 * Marker for non-attackable NPCs. Braun result yellow, kept clearly
	 * yellower than AMBER so the pointing accent stays unique.
	 */
	static final Color RESULT_YELLOW = new Color(0xD4, 0xB8, 0x00);

	private Palette()
	{
	}

	static Color withAlpha(Color base, int alpha)
	{
		return new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha);
	}
}

package com.wayfarer;

import java.util.Collection;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.WorldType;

/**
 * Where other players are never marked. Showing which way nearby players are
 * works as a PK warning in PvP areas, which RuneLite does not accept, and
 * hiding them for everyone gives neither side the edge. The minimap still
 * shows them there, as it does for every player.
 */
final class PvpAreas
{
	/** Worlds built around fighting players, beyond what WorldType.isPvpWorld covers (PvP, Deadman). */
	private static final Set<WorldType> PVP_MINIGAME_WORLDS = EnumSet.of(WorldType.PVP_ARENA, WorldType.LAST_MAN_STANDING);

	private PvpAreas()
	{
	}

	/**
	 * @param inWilderness the game's own inside-Wilderness flag
	 * @param inPvpArea the game's PvP-area flag, set wherever players can attack each other
	 * @param worldTypes the current world's types
	 */
	static boolean hidesPlayers(boolean inWilderness, boolean inPvpArea, Collection<WorldType> worldTypes)
	{
		if (inWilderness || inPvpArea)
		{
			return true;
		}
		if (worldTypes == null || worldTypes.isEmpty())
		{
			return false;
		}
		if (WorldType.isPvpWorld(worldTypes))
		{
			return true;
		}
		for (WorldType type : worldTypes)
		{
			if (PVP_MINIGAME_WORLDS.contains(type))
			{
				return true;
			}
		}
		return false;
	}
}

package com.wayfarer;

import lombok.RequiredArgsConstructor;

/**
 * Strip length presets, shortest to longest, named for OSRS blades. Each
 * takes a share of the game view's width, clamped so the strip stays
 * readable in a small window and doesn't sprawl in a large one.
 */
@RequiredArgsConstructor
public enum StripLength
{
	DAGGER("Dagger", 0.25, 200, 300),
	SCIMITAR("Scimitar", 0.32, 220, 400),
	LONGSWORD("Longsword", 0.40, 240, 480),
	GODSWORD("Godsword", 0.55, 320, 720);

	private final String label;
	private final double viewportShare;
	private final int minWidth;
	private final int maxWidth;

	int width(int viewportWidth)
	{
		return Math.max(minWidth, Math.min(maxWidth, (int) (viewportWidth * viewportShare)));
	}

	@Override
	public String toString()
	{
		return label;
	}
}

